//! Sources for the reader and writer tests.
#![allow(dead_code)]

use std::{
    io::{self, Read},
    sync::{
        Arc,
        atomic::{AtomicU64, Ordering},
    },
};

use covalence_blob_verify::{Expected, HashFn};

/// Byte `i` of a generated stream.
pub fn byte(i: u64) -> u8 {
    (i.wrapping_mul(31) ^ (i >> 7)) as u8
}

/// `len` generated bytes.
pub fn pattern(len: usize) -> Vec<u8> {
    (0..len as u64).map(byte).collect()
}

/// A generated stream of `len` bytes, produced on demand, counting what it
/// has handed out.
pub struct Generated {
    pub next: u64,
    pub len: u64,
    pub produced: Arc<AtomicU64>,
}

impl Generated {
    pub fn new(len: u64) -> Self {
        Self {
            next: 0,
            len,
            produced: Arc::default(),
        }
    }

    /// The expected size and digest of `len` generated bytes, computed in
    /// constant memory.
    pub fn expected(hash: HashFn, len: u64) -> Expected {
        let mut source = Generated::new(len);
        let mut buf = vec![0; 1 << 16];
        let mut sha256 = <sha2::Sha256 as sha2::Digest>::new();
        let mut blake3 = blake3::Hasher::new();
        loop {
            let read = source.read(&mut buf).unwrap();
            if read == 0 {
                break;
            }
            sha2::Digest::update(&mut sha256, &buf[..read]);
            blake3.update(&buf[..read]);
        }
        let digest = match hash {
            HashFn::Sha256 => sha2::Digest::finalize(sha256).into(),
            _ => blake3.finalize().into(),
        };
        Expected::new(len, hash, digest)
    }
}

impl Read for Generated {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        let count = (self.len - self.next).min(buf.len() as u64) as usize;
        for (i, slot) in buf[..count].iter_mut().enumerate() {
            *slot = byte(self.next + i as u64);
        }
        self.next += count as u64;
        self.produced.fetch_add(count as u64, Ordering::SeqCst);
        Ok(count)
    }
}

/// A reader that returns at most `step` bytes per read.
pub struct Trickle<R> {
    pub inner: R,
    pub step: usize,
}

impl<R: Read> Read for Trickle<R> {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        let max = buf.len().min(self.step);
        self.inner.read(&mut buf[..max])
    }
}
